const raw = $json.text;

const cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleaned);

return {
  json: {
    relevance: parsed.relevance,
    reference_accuracy: parsed.reference_accuracy,
    completeness: parsed.completeness,
    instruction_compliance: parsed.instruction_compliance,
    hallucination_check: parsed.hallucination_check,
    overall_result: parsed.overall_result,
    reason: parsed.reason
  }
};

const items = $input.all();

const totalTests = items.length;

let passCount = 0;
let reviewCount = 0;
let failCount = 0;

let relevanceFails = 0;
let referenceAccuracyFails = 0;
let completenessFails = 0;
let instructionComplianceFails = 0;
let hallucinationFails = 0;

for (const item of items) {
  const d = item.json;

  if (d.Overall_Result === 'PASS') passCount++;
  if (d.Overall_Result === 'REVIEW') reviewCount++;
  if (d.Overall_Result === 'FAIL') failCount++;

  if (d.Relevance === 'FAIL') relevanceFails++;
  if (d.Reference_Accuracy === 'FAIL') referenceAccuracyFails++;
  if (d.Completeness === 'FAIL') completenessFails++;
  if (d.Instruction_Compliance === 'FAIL') instructionComplianceFails++;
  if (d.Hallucination_Check === 'FAIL') hallucinationFails++;
}

return [
  {
    json: {
      Run_ID: items[0]?.json?.Run_ID ?? null,
      Total_Tests: totalTests,
      Pass_Count: passCount,
      Review_Count: reviewCount,
      Fail_Count: failCount,
      Pass_Rate: totalTests ? Number(((passCount / totalTests) * 100).toFixed(2)) : 0,
      Review_Rate: totalTests ? Number(((reviewCount / totalTests) * 100).toFixed(2)) : 0,
      Fail_Rate: totalTests ? Number(((failCount / totalTests) * 100).toFixed(2)) : 0,
      Relevance_Fails: relevanceFails,
      Reference_Accuracy_Fails: referenceAccuracyFails,
      Completeness_Fails: completenessFails,
      Instruction_Compliance_Fails: instructionComplianceFails,
      Hallucination_Fails: hallucinationFails
    }
  }
];

const baseline = $input.first().json;
const current = $('Compute Run Metrics').first().json;

const total = Number(current.Total_Tests || 0);

const currentRelevance = total
  ? ((total - Number(current.Relevance_Fails || 0)) / total) * 100
  : 0;

const currentAccuracy = total
  ? ((total - Number(current.Reference_Accuracy_Fails || 0)) / total) * 100
  : 0;

const currentCompleteness = total
  ? ((total - Number(current.Completeness_Fails || 0)) / total) * 100
  : 0;

const currentCompliance = total
  ? ((total - Number(current.Instruction_Compliance_Fails || 0)) / total) * 100
  : 0;

const currentHallucination = total
  ? ((total - Number(current.Hallucination_Fails || 0)) / total) * 100
  : 0;

const baselinePassRate = Number(baseline.Pass_Rate || 0);
const currentPassRate = Number(current.Pass_Rate || 0);

const regression = Math.max(0, baselinePassRate - currentPassRate);

return [
  {
    json: {
      Run_ID: current.Run_ID,
      Baseline_Run_ID: baseline.Run_ID,

      Total_Tests: total,
      Passed: Number(current.Pass_Count || 0),
      Failed: Number(current.Fail_Count || 0),

      Current_Pass_Rate: currentPassRate,
      Baseline_Pass_Rate: baselinePassRate,

      Average_Relevance: Number(currentRelevance.toFixed(2)),
      Average_Accuracy: Number(currentAccuracy.toFixed(2)),
      Average_Completeness: Number(currentCompleteness.toFixed(2)),
      Average_Compliance: Number(currentCompliance.toFixed(2)),
      Average_Hallucination: Number(currentHallucination.toFixed(2)),

      Relevance_Change: Number(
        (currentRelevance - Number(baseline.Average_Relevance || 0)).toFixed(2)
      ),

      Accuracy_Change: Number(
        (currentAccuracy - Number(baseline.Average_Accuracy || 0)).toFixed(2)
      ),

      Completeness_Change: Number(
        (currentCompleteness - Number(baseline.Average_Completeness || 0)).toFixed(2)
      ),

      Compliance_Change: Number(
        (currentCompliance - Number(baseline.Average_Compliance || 0)).toFixed(2)
      ),

      Hallucination_Change: Number(
        (currentHallucination - Number(baseline.Average_Hallucination || 0)).toFixed(2)
      ),

      Regression_Percentage: Number(regression.toFixed(2)),

      Regression_Status:
        regression === 0
          ? 'NO REGRESSION'
          : regression <= 10
          ? 'REVIEW'
          : 'REGRESSION',

      Run_Date: new Date().toISOString()
    }
  }
];

const rows = $input.all().map(item => item.json);

// Current run ka Run_ID lo
const currentRunId = Number(
  $('Compute Run Metrics').first().json.Run_ID
);

// Sirf reviewed + current run se purane runs allow karo
const approved = rows.filter(row => {
  const isReviewed =
    row.Reviewed === true ||
    String(row.Reviewed).toLowerCase() === 'true';

  const runId = Number(row.Run_ID);

  return isReviewed && runId < currentRunId;
});

// Agar koi previous reviewed baseline nahi mila
if (approved.length === 0) {
  return [{ json: {} }];
}

// Latest previous reviewed baseline select karo
approved.sort((a, b) => {
  const runA = Number(a.Run_ID || 0);
  const runB = Number(b.Run_ID || 0);

  return runB - runA;
});

return [
  {
    json: approved[0]
  }
];
